    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    top_cols = {c for c, v in enumerate(grid[0]) if v != bg}
    bottom_cols = {c for c, v in enumerate(grid[-1]) if v != bg}
    left_rows = {r for r in range(h) if grid[r][0] != bg}
    right_rows = {r for r in range(h) if grid[r][-1] != bg}

    border_cells = ({(0, c) for c in top_cols} |
                    {(h - 1, c) for c in bottom_cols} |
                    {(r, 0) for r in left_rows} |
                    {(r, w - 1) for r in right_rows})
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in border_cells]
    if not markers:
        return out

    mark_color = grid[markers[0][0]][markers[0][1]]
    horizontal_bars = bool(top_cols or bottom_cols)

    for r, c in markers:
        out[r][c] = 4
        if horizontal_bars:
            # Choose the horizontal edge bar whose span is closest to this marker.
            top_dist = min((abs(c - x) for x in top_cols), default=w + h)
            bot_dist = min((abs(c - x) for x in bottom_cols), default=w + h)
            dr = -1 if top_dist < bot_dist else 1
            rr = r + dr
            while 0 <= rr < h:
                if grid[rr][c] == bg:
                    out[rr][c] = mark_color
                rr += dr
        else:
            left_dist = min((abs(r - x) for x in left_rows), default=w + h)
            right_dist = min((abs(r - x) for x in right_rows), default=w + h)
            dc = -1 if left_dist < right_dist else 1
            cc = c + dc
            while 0 <= cc < w:
                if grid[r][cc] == bg:
                    out[r][cc] = mark_color
                cc += dc
    return out
